// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager, IERC20, IGlpManager, IRewardRouterV2} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;

    function testFuzz_property(uint256 stakeAmt, uint256 time) public {
        vm.assume(stakeAmt > 0 && stakeAmt <= type(uint128).max);
        vm.assume(time > 900 && time < type(uint256).max / 2);

        MockToken tok = new MockToken();
        MockRouter router = new MockRouter();
        MockGlpManager mgr = new MockGlpManager();
        MockJuniorVault jv = new MockJuniorVault();

        c = new DnGmxBatchingManager();
        c.initialize(
            IERC20(address(tok)),
            IERC20(address(tok)),
            IRewardRouterV2(address(router)),
            IGlpManager(address(mgr)),
            address(jv),
            address(this)
        );

        // stake GLP through the only permitted caller (the junior vault)
        vm.prank(address(jv));
        c.depositToken(address(tok), stakeAmt, 0);

        // first drain past cooldown
        vm.warp(time);
        c.executeBatchDeposit();

        // second drain past cooldown
        vm.warp(time + 901);
        c.executeBatchDeposit();

        // General rule: total tokens transferred out by C must equal exactly the
        // total staked amount; C must never send more than it tracked.
        assertTrue(tok.totalSent() == stakeAmt);
    }
}

